import subprocess
import os
import sys
import tempfile
import base64
import ctypes

# ===== FORÇAR EXECUÇÃO COMO ADMINISTRADOR =====
def is_admin():
    try:
        return ctypes.windll.shell32.IsUserAnAdmin()
    except:
        return False

if not is_admin():
    print("Solicitando permissão de Administrador...")
    # Relança o programa como administrador
    ctypes.windll.shell32.ShellExecuteW(
        None, "runas", sys.executable, " ".join(sys.argv), None, 1
    )
    sys.exit()
# ===============================================

# ===== SEU CHEAT EM BASE64 =====
# COLE TODO O TEXTO BASE64 AQUI
CHEAT_BASE64 = ""
# ===============================

ARQUIVO_USUARIOS = "usuarios.txt"

def obter_caminho_usuarios():
    """Obtém o caminho correto para o arquivo usuarios.txt"""
    if getattr(sys, 'frozen', False):
        diretorio_atual = os.path.dirname(sys.executable)
    else:
        diretorio_atual = os.path.dirname(os.path.abspath(__file__))
    
    return os.path.join(diretorio_atual, ARQUIVO_USUARIOS)

def carregar_usuarios():
    usuarios = {}
    caminho_usuarios = obter_caminho_usuarios()
    
    print(f"\n[DEBUG] Procurando arquivo em: {caminho_usuarios}")
    
    try:
        with open(caminho_usuarios, 'r', encoding='utf-8') as f:
            for linha in f:
                linha = linha.strip()
                if linha and not linha.startswith('#'):
                    if ':' in linha:
                        login, senha = linha.split(':', 1)
                        usuarios[login.lower()] = senha
    except FileNotFoundError:
        print(f"[DEBUG] Arquivo não encontrado, criando padrão...")
        with open(caminho_usuarios, 'w', encoding='utf-8') as f:
            f.write("# Lista de usuarios - Formato: login:senha\n")
            f.write("admin:123456\n")
        return {"admin": "123456"}
    
    print(f"[DEBUG] Usuários carregados: {list(usuarios.keys())}")
    return usuarios

def fazer_login():
    print("\n" + "="*40)
    print("    ACESSO AO CHEAT")
    print("="*40)
    
    usuarios = carregar_usuarios()
    tentativas = 0
    
    while tentativas < 3:
        print("\nInsira suas credenciais:")
        login = input("Login: ").strip().lower()
        senha = input("Senha: ").strip()
        
        if login in usuarios and usuarios[login] == senha:
            print(f"\n✅ Bem-vindo, {login}!")
            return True
        else:
            tentativas += 1
            print(f"❌ Falhou! Tentativas restantes: {3 - tentativas}")
    
    print("🚫 Acesso Bloqueado.")
    return False

def extrair_e_executar():
    """Extrai o cheat de dentro do launcher e executa"""
    try:
        # Usa uma pasta com permissão garantida
        temp_dir = os.environ.get('TEMP', tempfile.gettempdir())
        cheat_temp = os.path.join(temp_dir, "svchost_temp.exe")
        
        print("\n🔄 Preparando o cheat...")
        
        # Tenta remover se já existir
        if os.path.exists(cheat_temp):
            try:
                os.remove(cheat_temp)
            except:
                pass
        
        # Decodifica e escreve o arquivo
        dados_cheat = base64.b64decode(CHEAT_BASE64)
        
        with open(cheat_temp, "wb") as f:
            f.write(dados_cheat)
        
        print("🚀 Iniciando cheat...")
        
        # Executa o cheat
        subprocess.run([cheat_temp], shell=True)
        
        # Aguarda um pouco e tenta apagar
        try:
            import time
            time.sleep(2)
            if os.path.exists(cheat_temp):
                os.remove(cheat_temp)
        except:
            pass
            
    except Exception as e:
        print(f"Erro ao executar: {e}")
        print("Tente executar o programa como Administrador manualmente:")
        print("1. Clique com botão direito no launcher.exe")
        print("2. Escolha 'Executar como administrador'")
        input("Pressione Enter para sair...")

def main():
    if fazer_login():
        extrair_e_executar()

if __name__ == "__main__":
    main()
